174: // InstructionPayload builds the instruction context for a format and delimiter mode.
175: func InstructionPayload(format string, delimiters bool) (string, error) {
176: 	source, err := os.ReadFile("AIL_RULES/project-rules.ail")
177: 	if err != nil {
178: 		return "", err
179: 	}
180: 	parsed := parser.Parse(string(source), "project-rules.ail")
181: 	ir := interpreter.Interpret(parsed).IR
182: 
183: 	if strings.EqualFold(format, "markdown") {
184: 		baseline, err := os.ReadFile("MARKDOWN_BASELINE/project-rules.md")
185: 		if err != nil {
186: 			return "", err
187: 		}
188: 		if !delimiters {
189: 			return string(baseline), nil
190: 		}
191: 		return renderer.InterpretationInstruction() + "\n\n" + renderer.BeginMarker() + "\n\n" +
192: 			string(baseline) + "\n" + renderer.EndMarker() + "\n", nil
193: 	}
194: 
195: 	include := delimiters
196: 	result := renderer.Render(ir, core.RenderOptions{
197: 		Host:              core.HostOpenCode,
198: 		Mode:              core.ModeInline,
199: 		IncludeDelimiters: &include,
200: 	})
201: 	return result.Text, nil
202: }
