368: // prepareWorkspace creates an isolated directory and writes the task baseline into it.
369: func prepareWorkspace(root, id string, task Task) (string, error) {
370: 	dir := filepath.Join(root, id)
371: 	if err := os.MkdirAll(dir, 0o755); err != nil {
372: 		return "", err
373: 	}
374: 	names := make([]string, 0, len(task.Files))
375: 	for name := range task.Files {
376: 		names = append(names, name)
377: 	}
378: 	sort.Strings(names)
379: 	for _, name := range names {
380: 		path := filepath.Join(dir, name)
381: 		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
382: 			return "", err
383: 		}
384: 		if err := os.WriteFile(path, []byte(task.Files[name]), 0o644); err != nil {
385: 			return "", err
386: 		}
387: 	}
388: 	return dir, nil
389: }
